<template><div class="editor-panel">
<div class="section"><h3 class="section-title">Tipo de mensaje</h3><div class="tabs"><button v-for="tab in typeTabs" :key="tab.value" class="tab-btn" :class="{active:activeType===tab.value}" @click="activeType=tab.value">{{tab.label}}</button></div><p class="helper">La previsualización central mostrará exactamente este tipo y su comportamiento.</p></div>
<div class="section" v-if="currentConfig"><div class="controls-grid"><ColorPicker v-model="color" label="Color"/><ColorPicker v-model="background" label="Fondo"/><ColorPicker v-model="border" label="Borde"/><SliderControl v-model="borderRadius" label="Border radius" :min="0" :max="24" unit="px"/></div></div>
<div class="divider"></div><div class="section"><h3 class="section-title">Comportamiento global</h3><div class="controls-grid"><SelectControl v-model="displayType" label="Tipo de visualización" :options="displayOptions"/><SelectControl v-if="displayType==='toast'" v-model="toastPosition" label="Posición del Toast" :options="positionOptions"/><SliderControl v-if="displayType==='toast'" v-model="toastDuration" label="Duración" :min="1000" :max="10000" :step="500" unit="ms"/></div></div>
</div></template>
<script setup>
import {computed} from 'vue';import {useThemeStore} from '@/stores/themeStore.js';import {useAppStore} from '@/stores/appStore.js';import ColorPicker from '@/components/common/ColorPicker.vue';import SliderControl from '@/components/common/SliderControl.vue';import SelectControl from '@/components/common/SelectControl.vue'
const t=useThemeStore(),a=useAppStore();const typeTabs=[{value:'success',label:'Éxito'},{value:'warning',label:'Advertencia'},{value:'error',label:'Error'},{value:'info',label:'Información'}];const displayOptions=[{value:'modal',label:'Modal'},{value:'toast',label:'Toast'}];const positionOptions=[{value:'top-right',label:'Arriba derecha'},{value:'top-left',label:'Arriba izquierda'},{value:'bottom-right',label:'Abajo derecha'},{value:'bottom-left',label:'Abajo izquierda'},{value:'center',label:'Centro'}];const activeType=computed({get:()=>a.componentSelection.states,set:v=>a.setComponentSelection('states',v)});const currentConfig=computed(()=>t.theme.states[activeType.value]);const b=p=>computed({get:()=>currentConfig.value?.[p],set:v=>t.updateState(activeType.value,p,v)});const color=b('color'),background=b('background'),border=b('border'),borderRadius=b('borderRadius');const displayType=computed({get:()=>t.theme.states.displayType||'toast',set:v=>t.updateStateProp('displayType',v)}),toastPosition=computed({get:()=>t.theme.states.toastPosition||'top-right',set:v=>t.updateStateProp('toastPosition',v)}),toastDuration=computed({get:()=>t.theme.states.toastDuration||4000,set:v=>t.updateStateProp('toastDuration',v)})
</script><style scoped>.editor-panel{display:flex;flex-direction:column;gap:24px;padding:16px}.section{display:flex;flex-direction:column;gap:12px}.section-title{font-size:14px;font-weight:600;color:var(--tool-text,#334155);margin:0}.tabs{display:flex;flex-wrap:wrap;gap:8px}.tab-btn{padding:7px 11px;background:#fff;border:1px solid #d1d5db;border-radius:6px;font-size:12px;cursor:pointer;color:#475569}.tab-btn.active{background:#eff6ff;border-color:var(--tool-accent,#2563eb);color:var(--tool-accent,#2563eb);font-weight:600}.controls-grid{display:grid;grid-template-columns:1fr;gap:14px}.helper{font-size:12px;color:#64748b;line-height:1.45}.divider{height:1px;background:#e5e7eb}</style>